        mov     word [lineSlice__col], 0
        mov     word [lineSlice__count], 63
        mov     ax, buf                     ; link-time constant
        mov     [lineSlice__at], ax
        call    lineSlice
        mov     ax, [lineSlice__ret]
        mov     [showLine__n], ax
; ---- buf[n] = '$'
        mov     bx, ax
        mov     byte [buf + bx], 36
; ---- putStr( addr( buf ) )
        mov     ax, buf                     ; link-time constant
        mov     [putStr__at], ax
        call    putStr
; ---- newline()
        call    newline
        ret

; ============================================== sub put ====

put:
; ---- for ( u16 i = 0; i < n; i++ ) {
        mov     word [put__i], 0
.L284:
        mov     ax, [put__i]
        mov     bx, [put__n]
        cmp     ax, bx
        jae     .L286                       ; unsigned <
; ---- lineAppend( 0, peek8( at + i ) )
        mov     word [lineAppend__ln], 0
        mov     ax, [put__at]
        mov     bx, [put__i]
        add     ax, bx
        mov     bx, ax
        mov     al, [bx]                    ; peek8 - unchecked, by design
        mov     [lineAppend__ch], al        ; u8 -> u8, no widening
        call    lineAppend
.L285:
        inc     word [put__i]
        jmp     .L284
.L286:
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

